import pandas as pd

# Function to check the integrity and availability of telemetry data sources

def check_data_availability(file_path):
    try:
        df = pd.read_parquet(file_path)
        return {'status': 'available', 'row_count': len(df)}
    except Exception as e:
        return {'status': 'unavailable', 'error': str(e)}

# List of telemetry data sources
telemetry_sources = {
    'metric_node': '/telemetry/row/metric/metric_node.parquet',
    'metric_container': '/telemetry/row/metric/metric_container.parquet',
    'metric_service': '/telemetry/row/metric/metric_service.parquet',
    'metric_middleware': '/telemetry/row/metric/metric_middleware.parquet',
    'metric_app': '/telemetry/row/metric/metric_app.parquet',
    'trace_span': '/telemetry/row/trace/trace_span.parquet',
    'metric_stats': '/telemetry/metric_stats.parquet'
}

# Check the availability of each telemetry data source
availability_report = {key: check_data_availability(value) for key, value in telemetry_sources.items()}

# Return the availability report
availability_report
